                $birthdayInSameYearAsNow = $member['birthday']->setDate(
                    (int) $today->format('Y'),
                    (int) $member['birthday']->format('m'),
                    (int) $member['birthday']->format('d')
                );

                $birthday = $birthdayInSameYearAsNow->setDate(
